import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-vercel-postgres'

/**
 * Band themes become roles (docs/composer-roadmap.md, Section 5): one
 * vocabulary for every block's `theme`, the Section's and the five legacy
 * blocks', stated in src/blocks/shared/band-theme.ts. Ported from sas-site's
 * `band_theme_roles` (sas-site 20261001_183459), plus the legacy enums this
 * site still carries.
 *
 *   blocks:   light -> default, dark -> inverted (neutral, brand unchanged)
 *   Section:  inherit -> default, secondary -> neutral, accent -> brand
 *             (inverted unchanged)
 *   legacy (content, mediaBlock, archive, slider, tabs, and the slider
 *   groups inside a Columns column and a Tab slider tab, `slider_theme`):
 *             system -> default, light -> default, dark -> inverted
 *
 * Legacy `light` and `system` rendered the same light palette (`system` never
 * followed the visitor), and `dark` the dark one, so a light visit renders
 * as before. On a dark visit `default` now follows the visitor and
 * `inverted` paints the light palette, which is the point of the change.
 *
 * Drizzle recreates each enum through text and casts back blind to the data,
 * so every column is rewritten to the new names between the two steps (the
 * `UPDATE`s), and `down` maps them back the same way. Any other value cannot
 * exist: the column was enum-typed. No two families share a legacy name with
 * different meanings, so one mapping serves every table on the way up.
 *
 * `down` is exact for blocks and Sections. For the legacy enums it is exact in
 * rendering, not in storage: `system` and `light` both became `default`, and
 * `default` maps back to `system`, which rendered as `light` did. A `neutral`
 * or `brand` set on a legacy block after this ran maps back to `system`.
 */

